              onClick={handleShowSessions}
              disabled={isSessionsLoading}
              className="px-3 py-1.5 text-sm border border-gray-300 rounded hover:bg-gray-50 disabled:opacity-50"
            >
              {isSessionsLoading ? 'Loading...' : 'Sessions'}
            </button>

            <div className="text-sm">
              {saveStatus === 'saving' && <span className="text-blue-600">Saving...</span>}
              {saveStatus === 'saved' && <span className="text-green-600">Saved</span>}
              {saveStatus === 'error' && (
                <span className="text-red-600 cursor-help" title={saveError || 'Error'}>
                  Error saving
                </span>
              )}
              {saveStatus === 'idle' && (
                <span className={hasUnsavedChanges ? 'text-amber-600' : 'text-gray-400'}>
                  {hasUnsavedChanges ? `${changedBlocks.length} unsaved` : '-'}
                </span>
              )}
            </div>
          </div>
        </div>

        {saveError && saveStatus === 'error' && (
          <div className="mt-2 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700">
            {saveError}
          </div>
        )}

        <div className="text-xs text-gray-500">
          Source document: {currentDoc.source_document_id ?? 'None'}
        </div>
      </div>

      <div ref={scrollContainerRef} className="flex-1 overflow-y-auto bg-gray-100">
        <div className="max-w-4xl mx-auto py-8 px-4 space-y-4">
          {draftBlocks.length === 0 ? (
            <div className="text-center text-gray-500 py-12">No blocks found in this document.</div>
          ) : (
            draftBlocks.map((block) => {
              const BlockComponent = getBlockComponent(block.block_type_id)
              const baselineProps = savedBlocksById.get(block.block_id)?.props || {}

              if (!BlockComponent) {
                return (
                  <div key={block.block_id} className="bg-white p-4 rounded shadow">
                    <div className="text-red-600">
                      Unknown block type: {block.block_type_id}
                    </div>
                    <pre className="text-xs text-gray-600 mt-2">
                      {JSON.stringify(block, null, 2)}
                    </pre>
                  </div>
                )
              }

              return (
                <BlockComponent
                  key={block.block_id}
                  block={block}
                  baselineProps={baselineProps}
                  onUpdate={handleBlockUpdate}
                  isReadOnly={false}
                />
              )
            })
          )}
        </div>
      </div>

      {showLineage && lineage && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 w-full max-w-3xl max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold">Document Lineage</h2>
              <button
                type="button"
                onClick={() => setShowLineage(false)}
                className="text-gray-500 hover:text-gray-800"
              >
                Close
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h3 className="font-semibold mb-2">Ancestors</h3>
                {lineage.ancestors.length === 0 ? (
                  <p className="text-sm text-gray-500">No ancestors</p>
                ) : (
                  <ul className="space-y-2">
                    {lineage.ancestors.map((node) => (
                      <li key={`ancestor-${node.document_id}`} className="text-sm border rounded p-2">
                        <div className="font-medium">{node.name}</div>
                        <div className="text-gray-500">ID: {node.document_id}</div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              <div>
                <h3 className="font-semibold mb-2">Descendants</h3>
                {lineage.descendants.length === 0 ? (
                  <p className="text-sm text-gray-500">No descendants</p>
                ) : (
                  <ul className="space-y-2">
                    {lineage.descendants.map((node) => (
                      <li key={`descendant-${node.document_id}`} className="text-sm border rounded p-2">
                        <div className="font-medium">{node.name}</div>
                        <div className="text-gray-500">ID: {node.document_id}</div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {showSessions && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 w-full max-w-2xl max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold">Edit Sessions</h2>
              <button
                type="button"
                onClick={() => setShowSessions(false)}
                className="text-gray-500 hover:text-gray-800"
              >
                Close
              </button>
            </div>
            {sessions.length === 0 ? (
              <p className="text-sm text-gray-500">No sessions found.</p>
            ) : (
              <ul className="space-y-2">
                {sessions.map((session) => (
                  <li key={session.session_id} className="border rounded p-3 text-sm">
                    <div>Editor user: {session.editor_user_id}</div>
                    <div>Start: {new Date(session.started_at).toLocaleString()}</div>
                    <div>
                      End:{' '}
                      {session.ended_at
                        ? new Date(session.ended_at).toLocaleString()
                        : 'Active / not ended'}
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  )
}
"}

{"content":"import { useState } from 'react'
import { useSessionStore } from '../stores/useSessionStore'

export default function LoginPage() {
  const [loginUsername, setLoginUsername] = useState('demo_user')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('password123')
  const [isRegisterMode, setIsRegisterMode] = useState(false)
  const [showSettings, setShowSettings] = useState(false)
  const [customBaseUrl, setCustomBaseUrl] = useState('')

  const { login, register, isLoading, error, baseUrl, setBaseUrl } = useSessionStore()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (isRegisterMode) {
      await register({ login: loginUsername, email, password })
    } else {
      await login({ login: loginUsername, password })
    }
  }

  const handleSaveSettings = () => {
    if (customBaseUrl.trim()) {
      setBaseUrl(customBaseUrl.trim())
    }
    setShowSettings(false)
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100">
      <div className="w-full max-w-md">
        <div className="bg-white rounded-lg shadow-xl p-8">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-gray-900">Techno-Notion</h1>
            <p className="text-gray-600 mt-2">
              {isRegisterMode ? 'Create your account' : 'Sign in to your account'}
            </p>
          </div>

          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-red-700 text-sm">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label
                htmlFor="login"
                className="block text-sm font-medium text-gray-700 mb-1"
              >
                Username
              </label>
              <input
                id="login"
                type="text"
                value={loginUsername}
                onChange={(e) => setLoginUsername(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                required
                disabled={isLoading}
              />
            </div>

            {isRegisterMode && (
              <div>
                <label
                  htmlFor="email"
                  className="block text-sm font-medium text-gray-700 mb-1"
                >
                  Email
                </label>
                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                  disabled={isLoading}
                />
              </div>
            )}

            <div>
              <label
                htmlFor="password"
                className="block text-sm font-medium text-gray-700 mb-1"
              >
                Password
              </label>
              <input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                required
                disabled={isLoading}
              />
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isLoading
                ? (isRegisterMode ? 'Creating account...' : 'Signing in...')
                : (isRegisterMode ? 'Register' : 'Sign in')}
            </button>
          </form>

          <div className="mt-4 text-center">
            <button
              onClick={() => setIsRegisterMode(!isRegisterMode)}
              className="text-sm text-blue-600 hover:text-blue-800"
            >
              {isRegisterMode
                ? 'Already have an account? Sign in'
                : "Don't have an account? Register"}
            </button>
          </div>

          <div className="mt-6 pt-6 border-t border-gray-200">
            <button
              onClick={() => {
                setCustomBaseUrl(baseUrl)
                setShowSettings(!showSettings)
              }}
              className="text-sm text-gray-600 hover:text-gray-900"
            >
              ⚙️ API Settings
            </button>

            {showSettings && (
              <div className="mt-4 p-4 bg-gray-50 rounded border border-gray-200">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  API Base URL
                </label>
                <input
                  type="text"
                  value={customBaseUrl}
                  onChange={(e) => setCustomBaseUrl(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm mb-2"
                  placeholder="http://127.0.0.1:8001"
                />
                <div className="text-xs text-gray-500 mb-3">
                  Current: {baseUrl}
                </div>
                <button
                  onClick={handleSaveSettings}
                  className="w-full bg-gray-600 text-white py-2 px-4 rounded-md hover:bg-gray-700 text-sm"
                >
                  Save Settings
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}
"}

{"content":"@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    @apply bg-gray-100 text-gray-900;
  }
}

@layer components {
  .tiptap {
    @apply outline-none min-h-[400px] bg-gray-100;
  }

  /* Remove white background from prose and ProseMirror containers */
  .tiptap.prose,
  .tiptap .ProseMirror {
    @apply bg-gray-100;
  }

  /* Visual separation with white block backgrounds */
  .tiptap > *,
  .tiptap .ProseMirror > * {
    background-color: white;
    border-radius: 0.375rem;
    padding: 0.75rem 0.5rem !important;
    margin-bottom: 0.75rem !important;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    transition: box-shadow 0.2s;
  }

  /* Reset prose margins inside blocks to respect our padding - but not for direct block children */
  .tiptap > * > *:not(ul):not(ol),
  .tiptap .ProseMirror > * > *:not(ul):not(ol) {
    margin-top: 0 !important;
    margin-bottom: 0 !important;
  }

  /* Fix list indentation - lists inside blocks */
  .tiptap ul,
  .tiptap ol,
  .tiptap .ProseMirror ul,
  .tiptap .ProseMirror ol {
    padding-left: 1.5rem !important;
  }

  /* Remove margins from lists that are direct block content */
  .tiptap > * ul,
  .tiptap > * ol,
  .tiptap .ProseMirror > * ul,
  .tiptap .ProseMirror > * ol {
    margin-top: 0 !important;
    margin-bottom: 0 !important;
  }

  /* Fix list item styling */
  .tiptap li,
  .tiptap .ProseMirror li {
    margin-left: 0 !important;
    margin-top: 0.25rem !important;
    margin-bottom: 0.25rem !important;
  }

  /* Ensure blocks don't collapse - add min-height and display */
  .tiptap > *,
  .tiptap .ProseMirror > * {
    min-height: 2rem;
    display: block;
  }

  /* Override prose line-height that might be collapsing */
  .tiptap.prose > *,
  .tiptap.prose .ProseMirror > * {
    line-height: 1.5;
  }

  /* Add subtle hover effect */
  .tiptap > *:hover {
    @apply shadow-md transition-shadow;
  }

  .tiptap p.is-editor-empty:first-child::before {
    color: #adb5bd;
    content: attr(data-placeholder);
    float: left;
    height: 0;
    pointer-events: none;
  }

  .tiptap-toolbar {
    @apply flex gap-1 p-2 border-b border-gray-200 bg-white flex-wrap;
  }

  .tiptap-toolbar button {
    @apply px-3 py-1.5 text-sm rounded hover:bg-gray-100 border border-gray-300;
  }

  .tiptap-toolbar button.is-active {
    @apply bg-gray-200;
  }
}
"}

{"content":"/**
 * Document Heading Block Component
 * Displays document metadata in a table format mimicking a title page
 */

import type { BlockComponentProps } from './BlockRegistry'
import { getFieldMaxLength } from '../../lib/blockFieldLimits'

function normalizeComparable(value: unknown): string {
  return value === null || value === undefined ? '' : String(value)
}

export default function DocumentHeadingBlock({
  block,
  baselineProps,
  onUpdate,
  isReadOnly = false,
}: BlockComponentProps) {
  const handleFieldChange = (field: string, value: unknown) => {
    onUpdate(block.block_id, {
      ...(block.props || {}),
      [field]: value,
    })
  }

  const isFieldDirty = (field: string) =>
    normalizeComparable(block.props?.[field]) !== normalizeComparable(baselineProps?.[field])

  const resetField = (field: string) => {
    const fallbackValue = field === 'name' ? 'Untitled Document' : ''
    handleFieldChange(field, baselineProps?.[field] ?? fallbackValue)
  }

  const renderResetButton = (field: string) => {
    if (isReadOnly || !isFieldDirty(field)) {
      return null
    }

    return (
      <button
        type="button"
        onClick={() => resetField(field)}
        className="h-8 w-8 flex-shrink-0 border border-red-300 rounded text-red-700 bg-red-50 hover:bg-red-100"
        title="Revert this parameter"
      >
        ↺
      </button>
    )
  }

  const renderTextField = (field: string, placeholder = '') => {
    const currentValue = normalizeComparable(block.props?.[field])
    const maxLength = getFieldMaxLength(block, field)
    const isDirty = isFieldDirty(field)

    if (isReadOnly) {
      return <span className="text-gray-900">{currentValue}</span>
    }

    return (
      <div className="w-full">
        <div className="flex items-start gap-2">
          <input
            type="text"
            value={currentValue}
            onChange={(event) => handleFieldChange(field, event.target.value)}
            className={`w-full px-2 py-1 border rounded ${
              isDirty ? 'border-red-300 bg-red-50' : 'border-gray-300'
            }`}
            maxLength={maxLength || undefined}
            placeholder={placeholder}
          />
          {renderResetButton(field)}
        </div>
      </div>
    )
  }

  const renderTextareaField = (field: string, rows: number) => {
    const currentValue = normalizeComparable(block.props?.[field])
    const maxLength = getFieldMaxLength(block, field)
    const isDirty = isFieldDirty(field)

    if (isReadOnly) {
      return <span className="text-gray-900 whitespace-pre-wrap">{currentValue}</span>
    }

    return (
      <div className="w-full">
        <div className="flex items-start gap-2">
          <textarea
            value={currentValue}
            onChange={(event) => handleFieldChange(field, event.target.value)}
            className={`w-full px-2 py-1 border rounded ${
              isDirty ? 'border-red-300 bg-red-50' : 'border-gray-300'
            }`}
            rows={rows}
            maxLength={maxLength || undefined}
          />
          {renderResetButton(field)}
        </div>
      </div>
    )
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow-sm">
      <div className="text-center mb-6">
        {isReadOnly ? (
          <h1 className="text-3xl font-bold text-gray-900">
            {normalizeComparable(block.props?.name) || 'Untitled Document'}
          </h1>
        ) : (
          <div className="flex items-start gap-2">
            <input
              type="text"
              value={normalizeComparable(block.props?.name)}
              onChange={(event) => handleFieldChange('name', event.target.value)}
              className={`w-full text-center text-3xl font-bold text-gray-900 px-2 py-1 border rounded ${
                isFieldDirty('name') ? 'border-red-300 bg-red-50' : 'border-gray-300'
              }`}
              maxLength={getFieldMaxLength(block, 'name')}
              placeholder="Document Title"
            />
            {renderResetButton('name')}
          </div>
        )}
      </div>

      <table className="w-full border-collapse">
        <tbody>
          <tr className="border-b">
            <td className="py-2 px-4 font-semibold bg-gray-50 w-1/3">Heat No:</td>
            <td className="py-2 px-4">{renderTextField('heat_no')}</td>
          </tr>
          <tr className="border-b">
            <td className="py-2 px-4 font-semibold bg-gray-50">Finished Size:</td>
            <td className="py-2 px-4">{renderTextField('finished_size')}</td>
          </tr>
          <tr className="border-b">
            <td className="py-2 px-4 font-semibold bg-gray-50">Stock Size:</td>
            <td className="py-2 px-4">{renderTextField('stock_size')}</td>
          </tr>
          <tr className="border-b">
            <td className="py-2 px-4 font-semibold bg-gray-50">Stock Weight [kg]:</td>
            <td className="py-2 px-4">{renderTextField('stock_weight')}</td>
          </tr>
          <tr className="border-b">
            <td className="py-2 px-4 font-semibold bg-gray-50">Remarks:</td>
            <td className="py-2 px-4">{renderTextareaField('remarks', 3)}</td>
          </tr>
          <tr>
            <td className="py-2 px-4 font-semibold bg-gray-50">Created At:</td>
            <td className="py-2 px-4">
              <span className="text-gray-600 text-sm">
                {block.props.created_at
                  ? new Date(block.props.created_at).toLocaleString()
                  : 'N/A'}
              </span>
            </td>
          </tr>
          <tr>
            <td className="py-2 px-4 font-semibold bg-gray-50">Last Edited:</td>
            <td className="py-2 px-4">
              <span className="text-gray-600 text-sm">
                {block.props.updated_at
                  ? new Date(block.props.updated_at as string).toLocaleString()
                  : 'N/A'}
              </span>
            </td>
          </tr>
        </tbody>
      </table>

      {block.props.version && (
        <div className="mt-6 pt-6 border-t">
          <h3 className="text-lg font-semibold mb-3">Version Information</h3>
          <table className="w-full border-collapse">
            <tbody>
              <tr className="border-b">
                <td className="py-2 px-4 font-semibold bg-gray-50 w-1/3">Version Name:</td>
                <td className="py-2 px-4">{block.props.version.name || 'N/A'}</td>
              </tr>
              <tr className="border-b">
                <td className="py-2 px-4 font-semibold bg-gray-50">Editable:</td>
                <td className="py-2 px-4">
                  {block.props.version.is_editable ? 'Yes' : 'No'}
                </td>
              </tr>
              <tr>
                <td className="py-2 px-4 font-semibold bg-gray-50">Operations Count:</td>
                <td className="py-2 px-4">{block.props.version.operations_count ?? 0}</td>
              </tr>
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}"}

{"content":"/**
 * Input Workpiece Block Component
 * Displays and edits input workpiece parameters with dynamic geometry types
 */

import type { BlockComponentProps } from './BlockRegistry'

interface GeometryType {
  id: string
  name: string
  labels: string[]
  columns: string[]
}

function normalizeComparable(value: unknown): string {
  return value === null || value === undefined ? '' : String(value)
}

export default function InputWorkpieceBlock({
  block,
  baselineProps,
  onUpdate,
  isReadOnly = false,
}: BlockComponentProps) {
  const handleFieldChange = (field: string, value: unknown) => {
    onUpdate(block.block_id, {
      ...(block.props || {}),
      [field]: value,
    })
  }

  const handleAttributeChange = (attrName: string, value: string) => {
    onUpdate(block.block_id, {
      ...(block.props || {}),
      attributes: {
        ...(block.props?.attributes || {}),
        [attrName]: value,
      },
    })
  }

  const handleGeometryTypeChange = (newTypeId: string) => {
    const selectedType = availableGeometryTypes.find((t) => t.id === newTypeId)
    const newAttributes: Record<string, string> = {}

    if (selectedType) {
      selectedType.columns.forEach((col) => {
        newAttributes[col] = ''
      })
    }

    onUpdate(block.block_id, {
      ...(block.props || {}),
      geometry_type_id: newTypeId,
      attributes: newAttributes,
    })
  }

  const resetField = (field: string) => {
    handleFieldChange(field, baselineProps?.[field] ?? '')
  }

  const resetGeometryType = () => {
    onUpdate(block.block_id, {
      ...(block.props || {}),
      geometry_type_id: baselineProps?.geometry_type_id ?? '',
      attributes: {
        ...(baselineProps?.attributes || {}),
      },
    })
  }

  const resetAttribute = (attrName: string) => {
    const baselineValue = baselineProps?.attributes?.[attrName] ?? ''
    handleAttributeChange(attrName, normalizeComparable(baselineValue))
  }

  const availableGeometryTypes: GeometryType[] = block.props.available_geometry_types || []

  const currentGeometryTypeId = normalizeComparable(block.props.geometry_type_id)
  const currentGeometry = currentGeometryTypeId
    ? availableGeometryTypes.find((g) => g.id === currentGeometryTypeId)
    : null

  const selectedGeometry = currentGeometry || block.props.selected_geometry || null
  const title = block.props.title || 'Input Workpiece'

  const isFieldDirty = (field: string) =>
    normalizeComparable(block.props?.[field]) !== normalizeComparable(baselineProps?.[field])

  const isAttributeDirty = (attrName: string) =>
    normalizeComparable(block.props?.attributes?.[attrName]) !==
    normalizeComparable(baselineProps?.attributes?.[attrName])

  const renderResetButton = (onClick: () => void, dirty: boolean) => {
    if (isReadOnly || !dirty) {
      return null
    }

    return (
      <button
        type="button"
        onClick={onClick}
        className="h-8 w-8 flex-shrink-0 border border-red-300 rounded text-red-700 bg-red-50 hover:bg-red-100"
        title="Revert this parameter"
      >
        ↺
      </button>
    )
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow-sm">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold text-gray-900">{title}</h2>
      </div>

      <table className="w-full border-collapse">
        <tbody>
          <tr className="border-b">
            <td className="py-3 px-4 font-semibold bg-gray-50 w-1/2">Geometry Type:</td>
            <td className="py-3 px-4">
              {isReadOnly ? (
                <span className="text-gray-900">
                  {selectedGeometry ? selectedGeometry.library_name : 'Not set'}
                </span>
              ) : (
                <div className="flex items-start gap-2">
                  <select
                    value={normalizeComparable(block.props.geometry_type_id)}
                    onChange={(event) => handleGeometryTypeChange(event.target.value)}
                    className={`w-full px-2 py-1 border rounded ${
                      isFieldDirty('geometry_type_id')
                        ? 'border-red-300 bg-red-50'
                        : 'border-gray-300'
                    }`}
                  >
                    <option value="">Select geometry type...</option>
                    {availableGeometryTypes.map((geom) => (
                      <option key={geom.id} value={geom.id}>
                        {geom.name}
                      </option>
                    ))}
                  </select>
                  {renderResetButton(
                    resetGeometryType,
                    isFieldDirty('geometry_type_id')
                  )}
                </div>
              )}
            </td>
          </tr>

          {selectedGeometry &&
            selectedGeometry.columns.map((colName: string, index: number) => {
              const label = selectedGeometry.labels[index] || colName
              const currentValue = normalizeComparable(block.props.attributes?.[colName])
              const dirty = isAttributeDirty(colName)

              return (
                <tr key={colName} className="border-b">
                  <td className="py-3 px-4 font-semibold bg-gray-50">{label}</td>
                  <td className="py-3 px-4">
                    {isReadOnly ? (
                      <span className="text-gray-900">{currentValue || '-'}</span>
                    ) : (
                      <div className="flex items-start gap-2">
                        <input
                          type="number"
                          step="0.001"
                          value={currentValue}
                          onChange={(event) => handleAttributeChange(colName, event.target.value)}
                          className={`w-full px-2 py-1 border rounded ${
                            dirty ? 'border-red-300 bg-red-50' : 'border-gray-300'
                          }`}
                          placeholder={`Enter ${label.toLowerCase()}`}
                        />
                        {renderResetButton(() => resetAttribute(colName), dirty)}
                      </div>
                    )}
                  </td>
                </tr>
              )
            })}

          <tr className="border-b">
            <td className="py-3 px-4 font-semibold bg-gray-50">Weight [kg]:</td>
            <td className="py-3 px-4">
              {isReadOnly ? (
                <span className="text-gray-900">{block.props.weight ?? 0}</span>
              ) : (
                <div className="flex items-start gap-2">
                  <input
                    type="number"
                    step="0.001"
                    min="0"
                    value={normalizeComparable(block.props.weight)}
                    onChange={(event) => handleFieldChange('weight', event.target.value)}
                    className={`w-full px-2 py-1 border rounded ${
                      isFieldDirty('weight') ? 'border-red-300 bg-red-50' : 'border-gray-300'
                    }`}
                  />
                  {renderResetButton(() => resetField('weight'), isFieldDirty('weight'))}
                </div>
              )}
            </td>
          </tr>

          <tr>
            <td className="py-3 px-4 font-semibold bg-gray-50">
              Elements across width [pcs]:
            </td>
            <td className="py-3 px-4">
              {isReadOnly ? (
                <span className="text-gray-900">{block.props.mesh_elements ?? 0}</span>
              ) : (
                <div className="flex items-start gap-2">
                  <input
                    type="number"
                    step="1"
                    min="0"
                    value={normalizeComparable(block.props.mesh_elements)}
                    onChange={(event) => handleFieldChange('mesh_elements', event.target.value)}
                    className={`w-full px-2 py-1 border rounded ${
                      isFieldDirty('mesh_elements')
                        ? 'border-red-300 bg-red-50'
                        : 'border-gray-300'
                    }`}
                  />
                  {renderResetButton(
                    () => resetField('mesh_elements'),
                    isFieldDirty('mesh_elements')
                  )}
                </div>
              )}
            </td>
          </tr>
        </tbody>
      </table>

      {block.is_system && (
        <div className="mt-4 text-xs text-gray-500 italic">
          * This is a required system block and cannot be removed
        </div>
      )}
    </div>
  )
}"}

{"content":"import { create } from 'zustand'
import { apiClient } from '../lib/apiClient'
import type {
  CreateDocumentRequest,
  CreateProjectRequest,
  Document,
  DocumentDiffResponse,
  DocumentListResponse,
  Project,
  ProjectListResponse,
} from '../types/api'
import { extractField } from '../lib/utils'

interface DocumentsState {
  projects: Project[]
  currentProjectId: string | null
  documents: Document[]
  currentDocId: string | null
  currentDoc: Document | null
  isLoading: boolean
  error: string | null
  showDeleted: boolean
  selectedDocIds: Set<string>

  fetchProjects: () => Promise<void>
  createProject: (name: string, notes?: string) => Promise<Project | null>
  setCurrentProject: (id: string | null) => void

  fetchDocuments: (projectId?: string | null) => Promise<void>
  createDocument: (name: string, notes?: string, sourceDocumentId?: string) => Promise<Document | null>
  copyDocument: (id: string, name?: string) => Promise<Document | null>
  fetchDocument: (id: string) => Promise<Document | null>
  setCurrentDoc: (id: string | null) => void
  updateLocalDoc: (id: string, updates: Partial<Document>) => void
  updateDocument: (id: string, updates: Partial<Document>) => Promise<boolean>
  deleteDocument: (id: string) => Promise<boolean>
  deleteMultipleDocuments: (ids: string[]) => Promise<void>
  getDiff: (leftId: string, rightId: string) => Promise<DocumentDiffResponse | null>

  setShowDeleted: (show: boolean) => void
  toggleDocSelection: (id: string) => void
  clearSelection: () => void
  selectAll: (docIds: string[]) => void
}

function normalizeProject(project: Partial<Project>): Project {
  const id = String(project.id || project.project_id || '')
  return {
    ...project,
    id,
    project_id: project.project_id ?? (id ? Number(id) : undefined),
    user_id: project.user_id ?? 0,
    name: project.name || '',
  } as Project
}

function normalizeDocument(document: Partial<Document>): Document {
  const id = String(document.id || document.document_id || '')
  return {
    ...document,
    id,
    document_id: document.document_id ?? (id ? Number(id) : undefined),
    project_id: document.project_id ?? 0,
    name: document.name || '',
  } as Document
}

export const useDocumentsStore = create<DocumentsState>((set, get) => ({
  projects: [],
  currentProjectId: null,
  documents: [],
  currentDocId: null,
  currentDoc: null,
  isLoading: false,
  error: null,
  showDeleted: false,
  selectedDocIds: new Set<string>(),

  fetchProjects: async () => {
    set({ isLoading: true, error: null })
    const response = await apiClient.get<ProjectListResponse>('/projects')

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch projects',
      })
      return
    }

    const projects = extractField<Project[]>(
      response.data as Record<string, unknown>,
      'projects',
      'items',
      'data'
    ) || []

    const normalized = projects.map((project) => normalizeProject(project))
    const state = get()
    const nextProjectId =
      state.currentProjectId && normalized.some((project) => project.id === state.currentProjectId)
        ? state.currentProjectId
        : normalized[0]?.id || null

    set({
      projects: normalized,
      currentProjectId: nextProjectId,
      isLoading: false,
      error: null,
    })

    if (nextProjectId) {
      await get().fetchDocuments(nextProjectId)
    } else {
      set({ documents: [], currentDoc: null, currentDocId: null })
    }
  },

  createProject: async (name: string, notes?: string) => {
    set({ isLoading: true, error: null })
    const payload: CreateProjectRequest = { name, notes }

    const response = await apiClient.post<Project>('/projects', { body: payload })
    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to create project',
      })
      return null
    }

    const project = normalizeProject(response.data)
    set((state) => ({
      projects: [project, ...state.projects],
      currentProjectId: project.id,
      isLoading: false,
      error: null,
    }))
    await get().fetchDocuments(project.id)
    return project
  },

  setCurrentProject: (id: string | null) => {
    set({
      currentProjectId: id,
      documents: [],
      currentDocId: null,
      currentDoc: null,
      selectedDocIds: new Set<string>(),
    })
    if (id) {
      get().fetchDocuments(id)
    }
  },

  fetchDocuments: async (projectId?: string | null) => {
    const targetProjectId = projectId ?? get().currentProjectId
    if (!targetProjectId) {
      set({ documents: [], currentDoc: null, currentDocId: null })
      return
    }

    set({ isLoading: true, error: null })
    const response = await apiClient.get<DocumentListResponse>(`/projects/${targetProjectId}/documents`, {
      params: { include_deleted: get().showDeleted },
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch documents',
      })
      return
    }

    const documents = extractField<Document[]>(
      response.data as Record<string, unknown>,
      'documents',
      'items',
      'data'
    ) || []

    const normalized = documents.map((document) => normalizeDocument(document))
    const currentDoc = normalized.find((document) => document.id === get().currentDocId) || null

    set({
      documents: normalized,
      currentDoc,
      currentDocId: currentDoc?.id || null,
      isLoading: false,
      error: null,
    })
  },

  createDocument: async (name: string, notes?: string, sourceDocumentId?: string) => {
    const projectId = get().currentProjectId
    if (!projectId) {
      set({ error: 'Select a project first' })
      return null
    }

    set({ isLoading: true, error: null })
    const payload: CreateDocumentRequest = {
      project_id: Number(projectId),
      name,
      notes,
      source_document_id: sourceDocumentId ? Number(sourceDocumentId) : undefined,
    }

    const response = await apiClient.post<Document>('/documents', { body: payload })
    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to create document',
      })
      return null
    }

    const document = normalizeDocument(response.data)
    set((state) => ({
      documents: [document, ...state.documents],
      currentDoc: document,
      currentDocId: document.id,
      isLoading: false,
      error: null,
    }))
    return document
  },

  copyDocument: async (id: string, name?: string) => {
    const response = await apiClient.post<Document>(`/documents/${id}/copy`, {
      body: { name },
    })
    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to copy document' })
      return null
    }

    const copied = normalizeDocument(response.data)
    set((state) => ({
      documents: [copied, ...state.documents],
      currentDoc: copied,
      currentDocId: copied.id,
      error: null,
    }))
    return copied
  },

  fetchDocument: async (id: string) => {
    set({ isLoading: true, error: null })
    const response = await apiClient.get<Document>(`/documents/${id}`)

    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch document',
      })
      return null
    }

    const document = normalizeDocument(response.data)
    set({
      currentDoc: document,
      currentDocId: document.id,
      isLoading: false,
      error: null,
    })
    return document
  },

  setCurrentDoc: (id: string | null) => {
    if (id === null) {
      set({ currentDocId: null, currentDoc: null })
      return
    }
    const document = get().documents.find((entry) => entry.id === id)
    if (document) {
      set({ currentDocId: document.id, currentDoc: document })
      return
    }
    get().fetchDocument(id)
  },

  updateLocalDoc: (id: string, updates: Partial<Document>) => {
    set((state) => ({
      documents: state.documents.map((document) =>
        document.id === id ? { ...document, ...updates } : document
      ),
      currentDoc:
        state.currentDoc?.id === id ? { ...state.currentDoc, ...updates } : state.currentDoc,
    }))
  },

  updateDocument: async (id: string, updates: Partial<Document>) => {
    const response = await apiClient.patch<Document>(`/documents/${id}`, {
      body: updates,
    })

    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to update document' })
      return false
    }

    const normalized = normalizeDocument(response.data)
    set((state) => ({
      documents: state.documents.map((document) =>
        document.id === id ? { ...document, ...normalized } : document
      ),
      currentDoc:
        state.currentDoc?.id === id ? { ...state.currentDoc, ...normalized } : state.currentDoc,
      error: null,
    }))
    return true
  },

  deleteDocument: async (id: string) => {
    const response = await apiClient.delete(`/documents/${id}`)
    if (!response.ok) {
      set({ error: response.errorMessage || 'Failed to delete document' })
      return false
    }
    await get().fetchDocuments()
    return true
  },

  deleteMultipleDocuments: async (ids: string[]) => {
    const requests = ids.map((id) => apiClient.delete(`/documents/${id}`))
    await Promise.all(requests)
    set({ selectedDocIds: new Set<string>() })
    await get().fetchDocuments()
  },

  getDiff: async (leftId: string, rightId: string) => {
    const response = await apiClient.get<DocumentDiffResponse>(`/documents/${leftId}/diff/${rightId}`)
    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to diff documents' })
      return null
    }
    return response.data
  },

  setShowDeleted: (show: boolean) => {
    set({ showDeleted: show })
    get().fetchDocuments()
  },

  toggleDocSelection: (id: string) => {
    set((state) => {
      const updated = new Set(state.selectedDocIds)
      if (updated.has(id)) {
        updated.delete(id)
      } else {
        updated.add(id)
      }
      return { selectedDocIds: updated }
    })
  },

  clearSelection: () => {
    set({ selectedDocIds: new Set<string>() })
  },

  selectAll: (docIds: string[]) => {
    set({ selectedDocIds: new Set<string>(docIds) })
  },
}))
"}

{"content":"import { create } from 'zustand'
import { apiClient } from '../lib/apiClient'
import type { User, LoginRequest, LoginResponse, RegisterRequest } from '../types/api'
import { extractField } from '../lib/utils'

interface SessionState {
  token: string | null
  user: User | null
  baseUrl: string
  isAuthenticated: boolean
  isLoading: boolean
  error: string | null

  setBaseUrl: (url: string) => void
  login: (credentials: LoginRequest) => Promise<boolean>
  register: (data: RegisterRequest) => Promise<boolean>
  logout: () => void
  fetchMe: () => Promise<boolean>
  initialize: () => void
}

const TOKEN_KEY = 'techno-notion-token'
const BASE_URL_KEY = 'techno-notion-base-url'
const DEFAULT_BASE_URL = 'http://127.0.0.1:8001'

export const useSessionStore = create<SessionState>((set, get) => ({
  token: null,
  user: null,
  baseUrl: DEFAULT_BASE_URL,
  isAuthenticated: false,
  isLoading: false,
  error: null,

  setBaseUrl: (url: string) => {
    apiClient.setBaseUrl(url)
    const normalizedBaseUrl = apiClient.getBaseUrl()
    localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
    set({ baseUrl: normalizedBaseUrl })
  },

  login: async (credentials: LoginRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<LoginResponse>('/auth/login', {
      body: credentials,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Login failed',
      })
      return false
    }

    // Extract token from response (tolerant)
    const token = extractField<string>(
      response.data as Record<string, unknown>,
      'access_token',
      'token',
      'accessToken'
    )

    if (!token) {
      set({ isLoading: false, error: 'No token received from server' })
      return false
    }

    // Save token
    localStorage.setItem(TOKEN_KEY, token)
    apiClient.setToken(token)
    set({ token, isAuthenticated: true })

    // Fetch user info
    const success = await get().fetchMe()
    set({ isLoading: false })
    return success
  },

  register: async (data: RegisterRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<User>('/auth/register', {
      body: data,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Registration failed',
      })
      return false
    }

    // After successful registration, automatically log in
    set({ isLoading: false })
    return get().login({ login: data.login, password: data.password })
  },

  logout: () => {
    localStorage.removeItem(TOKEN_KEY)
    apiClient.setToken(null)
    set({
      token: null,
      user: null,
      isAuthenticated: false,
      error: null,
    })
  },

  fetchMe: async () => {
    const response = await apiClient.get<User>('/auth/me')

    if (!response.ok) {
      set({ error: response.errorMessage || 'Failed to fetch user info' })
      return false
    }

    set({ user: response.data || null, error: null })
    return true
  },

  initialize: () => {
    // Load base URL
    const savedBaseUrl = localStorage.getItem(BASE_URL_KEY)
    if (savedBaseUrl) {
      apiClient.setBaseUrl(savedBaseUrl)
      const normalizedBaseUrl = apiClient.getBaseUrl()
      if (normalizedBaseUrl !== savedBaseUrl) {
        localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
      }
      set({ baseUrl: normalizedBaseUrl })
    } else {
      apiClient.setBaseUrl(DEFAULT_BASE_URL)
      set({ baseUrl: apiClient.getBaseUrl() })
    }

    // Load token
    const savedToken = localStorage.getItem(TOKEN_KEY)
    if (savedToken) {
      apiClient.setToken(savedToken)
      set({ token: savedToken, isAuthenticated: true })

      // Fetch user info in background
      get().fetchMe()
    }
  },
}))
"}

{"content":"export interface ApiResponse<T = unknown> {
  ok: boolean
  status: number
  data?: T
  errorMessage?: string
  errorCode?: string
}

// Auth
export interface LoginRequest {
  login: string
  password: string
}

export interface LoginResponse {
  access_token?: string
  token?: string
  accessToken?: string
}

export interface RegisterRequest {
  login: string
  email: string
  password: string
}

export interface User {
  user_id: number
  login: string
  email: string
}

// Projects
export interface Project {
  id: string
  project_id?: number
  user_id: number
  material_id?: number | null
  name: string
  notes?: string | null
  created_at?: string
  updated_at?: string
  deleted_at?: string | null
}

export interface ProjectListResponse {
  projects?: Project[]
  items?: Project[]
  data?: Project[]
}

export interface CreateProjectRequest {
  name: string
  notes?: string
  material_id?: number
}

// Documents
export interface Document {
  id: string
  document_id?: number
  project_id: number
  source_document_id?: number | null
  editor_user_id?: number | null
  first_block_id?: string | null
  name: string
  notes?: string | null
  created_at?: string
  updated_at?: string
  deleted_at?: string | null
}

export interface DocumentListResponse {
  documents?: Document[]
  items?: Document[]
  data?: Document[]
}

export interface CreateDocumentRequest {
  project_id: number
  name: string
  notes?: string
  source_document_id?: number
  editor_user_id?: number
}

export interface CopyDocumentRequest {
  name?: string
  notes?: string
  editor_user_id?: number
}

// Blocks
export interface BlockData {
  block_id: string
  document_id: number
  previous_block_id: string | null
  next_block_id: string | null
  block_type_id: string
  props: Record<string, any>
  is_system: boolean
  is_removable: boolean
  fixed_position: number | null
  editable_fields?: string[]
  field_limits?: Record<string, number>
}

export interface Operation {
  op_type: 'insert_block' | 'delete_block' | 'move_block' | 'update_text' | 'update_props'
  data: Record<string, unknown>
}

export interface CommitRequest {
  ops: Operation[]
}

export interface CommitResponse {
  success: boolean
  message?: string
}

// Lineage + diff
export interface LineageNode {
  document_id: number
  source_document_id?: number | null
  name: string
  created_at: string
}

export interface DocumentLineageResponse {
