export interface BlockDiffEntry {
  index: number
  change_type: 'added' | 'removed' | 'modified'
  left_block_id?: string | null
  right_block_id?: string | null
  left_block_type_id?: string | null
  right_block_type_id?: string | null
  left_props?: Record<string, unknown> | null
  right_props?: Record<string, unknown> | null
}

export interface DocumentDiffResponse {
  left_document_id: number
  right_document_id: number
  left_name: string
  right_name: string
  total_changes: number
  changes: BlockDiffEntry[]
}

// Edit sessions
export interface EditSession {
  session_id: string
  document_id: number
  editor_user_id: number
  started_at: string
  ended_at?: string | null
}

export interface EditSessionListResponse {
  sessions: EditSession[]
  total: number
}

// Search
export interface SearchResult {
  block_id: string
  document_id: number
  snippet: string
  block_type_id: string
}

export interface SearchResponse {
  results: SearchResult[]
  total: number
}
"}

{"content":"from typing import List, Tuple
from uuid import UUID

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models.document.block import Block
from app.models.document.block_types import get_block_type_handler
from app.schemas import OperationPayload
from app.services.block_service import create_block, delete_block, move_block_after, update_block_props
from app.services.block_type_service import can_delete_block, can_reorder_block, validate_block_constraints


def apply_operations(
    db: Session,
    document_id: int,
    ops: List[OperationPayload],
) -> None:
    for op in ops:
        op_type = op.op_type
        data = op.data

        if op_type == "insert_block":
            block_type_id = str(data["block_type_id"])
            if not validate_block_constraints(db, document_id, block_type_id):
                raise ValueError(f"Cannot create block of type {block_type_id}: constraints violated")

            previous_block_id = data.get("previous_block_id")
            parsed_prev = UUID(previous_block_id) if previous_block_id else None
            block_id = UUID(data["block_id"]) if data.get("block_id") else None

            create_block(
                db=db,
                document_id=document_id,
                block_type_id=block_type_id,
                props=data.get("props", {}),
                previous_block_id=parsed_prev,
                block_id=block_id,
            )

        elif op_type == "delete_block":
            block_id = UUID(str(data["block_id"]))
            if not can_delete_block(db, block_id):
                raise ValueError(f"Cannot delete block {block_id}: block is not removable")
            if not delete_block(db, document_id, block_id):
                raise ValueError(f"Block {block_id} not found")

        elif op_type == "move_block":
            block_id = UUID(str(data["block_id"]))
            if not can_reorder_block(db, block_id):
                raise ValueError(f"Cannot reorder block {block_id}: block has fixed position")
            previous_block_id = data.get("previous_block_id")
            parsed_prev = UUID(str(previous_block_id)) if previous_block_id else None
            moved = move_block_after(db, document_id, block_id, parsed_prev)
            if not moved:
                raise ValueError(f"Block {block_id} not found")

        elif op_type == "update_props":
            block_id = UUID(str(data["block_id"]))
            block = update_block_props(db, block_id, data.get("props", {}))
            if not block:
                raise ValueError(f"Block {block_id} not found")

            handler = get_block_type_handler(block.block_type_id)
            if handler:
                handler.on_update(db, block.block_id, block.document_id, block.props)

        elif op_type == "update_text":
            block_id = UUID(str(data["block_id"]))
            block = db.execute(select(Block).filter(Block.block_id == block_id)).scalars().first()
            if not block:
                raise ValueError(f"Block {block_id} not found")
            props = dict(block.props or {})
            props["text"] = data.get("text", "")
            block.props = props

            handler = get_block_type_handler(block.block_type_id)
            if handler:
                handler.on_update(db, block.block_id, block.document_id, block.props)

        else:
            raise ValueError(f"Unsupported operation type: {op_type}")


def commit_operations(
    db: Session,
    document_id: int,
    ops: List[OperationPayload],
) -> Tuple[bool, str]:
    try:
        apply_operations(db, document_id, ops)
        db.commit()
        return True, "Operations applied"
    except Exception as exc:
        db.rollback()
        return False, str(exc)
"}

{"content":"from typing import List, Optional
from uuid import UUID, uuid4

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models.document.block import Block
from app.models.document.document import Document


def _get_document_or_none(db: Session, document_id: int) -> Optional[Document]:
    return db.execute(
        select(Document).filter(Document.document_id == document_id)
    ).scalars().first()


def get_ordered_blocks(db: Session, document_id: int) -> List[Block]:
    document = _get_document_or_none(db, document_id)
    if not document or not document.first_block_id:
        return []

    blocks_by_id = {
        block.block_id: block
        for block in db.execute(
            select(Block).filter(Block.document_id == document_id)
        ).scalars().all()
    }

    ordered: List[Block] = []
    current_id = document.first_block_id
    visited: set[UUID] = set()

    while current_id and current_id not in visited:
        visited.add(current_id)
        block = blocks_by_id.get(current_id)
        if not block:
            break
        ordered.append(block)
        current_id = block.next_block_id

    return ordered


def get_root_blocks(db: Session, document_id: int) -> List[Block]:
    return get_ordered_blocks(db, document_id)


def create_block(
    db: Session,
    document_id: int,
    block_type_id: str,
    props: dict,
    previous_block_id: Optional[UUID] = None,
    block_id: Optional[UUID] = None,
    *,
    is_system: bool = False,
    is_removable: bool = True,
    fixed_position: Optional[int] = None,
) -> Block:
    document = _get_document_or_none(db, document_id)
    if not document:
        raise ValueError("Document not found")

    if block_id is None:
        block_id = uuid4()

    new_block = Block(
        block_id=block_id,
        document_id=document_id,
        previous_block_id=None,
        next_block_id=None,
        block_type_id=block_type_id,
        props=props or {},
        is_system=is_system,
        is_removable=is_removable,
        fixed_position=fixed_position,
    )
    db.add(new_block)
    db.flush()

    # Insert at head
    if previous_block_id is None:
        old_head_id = document.first_block_id
        new_block.previous_block_id = None
        new_block.next_block_id = old_head_id
        document.first_block_id = new_block.block_id

        if old_head_id:
            old_head = db.execute(
                select(Block).filter(
                    Block.block_id == old_head_id,
                    Block.document_id == document_id,
                )
            ).scalars().first()
            if old_head:
                old_head.previous_block_id = new_block.block_id
        return new_block

    # Insert after a specific block
    prev_block = db.execute(
        select(Block).filter(
            Block.block_id == previous_block_id,
            Block.document_id == document_id,
        )
    ).scalars().first()
    if not prev_block:
        raise ValueError("previous_block_id not found in document")

    next_block_id = prev_block.next_block_id
    new_block.previous_block_id = prev_block.block_id
    new_block.next_block_id = next_block_id
    prev_block.next_block_id = new_block.block_id

    if next_block_id:
        next_block = db.execute(
            select(Block).filter(
                Block.block_id == next_block_id,
                Block.document_id == document_id,
            )
        ).scalars().first()
        if next_block:
            next_block.previous_block_id = new_block.block_id

    return new_block


def move_block_after(
    db: Session,
    document_id: int,
    block_id: UUID,
    previous_block_id: Optional[UUID],
) -> Optional[Block]:
    document = _get_document_or_none(db, document_id)
    if not document:
        return None

    block = db.execute(
        select(Block).filter(
            Block.block_id == block_id,
            Block.document_id == document_id,
        )
    ).scalars().first()
    if not block:
        return None

    if previous_block_id == block.block_id:
        raise ValueError("Block cannot reference itself as previous")

    # No-op if already in requested position
    if block.previous_block_id == previous_block_id:
        return block

    # Detach from current position
    prev_block = None
    next_block = None
    if block.previous_block_id:
        prev_block = db.execute(
            select(Block).filter(
                Block.block_id == block.previous_block_id,
                Block.document_id == document_id,
            )
        ).scalars().first()
    if block.next_block_id:
        next_block = db.execute(
            select(Block).filter(
                Block.block_id == block.next_block_id,
                Block.document_id == document_id,
            )
        ).scalars().first()

    if prev_block:
        prev_block.next_block_id = block.next_block_id
    else:
        document.first_block_id = block.next_block_id

    if next_block:
        next_block.previous_block_id = block.previous_block_id

    # Insert at head
    if previous_block_id is None:
        old_head_id = document.first_block_id
        block.previous_block_id = None
        block.next_block_id = old_head_id
        document.first_block_id = block.block_id

        if old_head_id and old_head_id != block.block_id:
            old_head = db.execute(
                select(Block).filter(
                    Block.block_id == old_head_id,
                    Block.document_id == document_id,
                )
            ).scalars().first()
            if old_head:
                old_head.previous_block_id = block.block_id
        return block

    # Insert after target previous block
    target_prev = db.execute(
        select(Block).filter(
            Block.block_id == previous_block_id,
            Block.document_id == document_id,
        )
    ).scalars().first()
    if not target_prev:
        raise ValueError("Target previous block not found")

    target_next_id = target_prev.next_block_id
    target_prev.next_block_id = block.block_id
    block.previous_block_id = target_prev.block_id
    block.next_block_id = target_next_id

    if target_next_id:
        target_next = db.execute(
            select(Block).filter(
                Block.block_id == target_next_id,
                Block.document_id == document_id,
            )
        ).scalars().first()
        if target_next:
            target_next.previous_block_id = block.block_id

    return block


def update_block_props(
    db: Session,
    block_id: UUID,
    props: dict,
) -> Optional[Block]:
    block = db.execute(
        select(Block).filter(Block.block_id == block_id)
    ).scalars().first()
    if not block:
        return None
    block.props = props or {}
    return block


def delete_block(db: Session, document_id: int, block_id: UUID) -> bool:
    document = _get_document_or_none(db, document_id)
    if not document:
        return False

    block = db.execute(
        select(Block).filter(
            Block.block_id == block_id,
            Block.document_id == document_id,
        )
    ).scalars().first()
    if not block:
        return False

    prev_block = None
    next_block = None
    if block.previous_block_id:
        prev_block = db.execute(
            select(Block).filter(
                Block.block_id == block.previous_block_id,
                Block.document_id == document_id,
            )
        ).scalars().first()
    if block.next_block_id:
        next_block = db.execute(
            select(Block).filter(
                Block.block_id == block.next_block_id,
                Block.document_id == document_id,
            )
        ).scalars().first()

    if prev_block:
        prev_block.next_block_id = block.next_block_id
    else:
        document.first_block_id = block.next_block_id

    if next_block:
        next_block.previous_block_id = block.previous_block_id

    db.delete(block)
    return True
"}

{"content":"from typing import List
from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.auth import get_current_user
from app.database import get_db
from app.models.document.block import Block
from app.models.user import User
from app.routers.document import check_document_access
from app.schemas import (
    BlockCreate,
    BlockMove,
    BlockResponse,
    BlockUpdate,
    CommitRequest,
    CommitResponse,
)
from app.services.block_service import create_block, delete_block, get_root_blocks, move_block_after, update_block_props
from app.services.block_type_service import (
    can_delete_block,
    can_reorder_block,
    enrich_block_data_for_frontend,
    validate_block_constraints,
)
from app.services.commit_service import commit_operations

router = APIRouter(tags=["blocks"])


@router.get("/documents/{document_id}/blocks/root", response_model=List[BlockResponse])
def get_document_root_blocks(
    document_id: int,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    check_document_access(db, document_id, current_user.user_id)
    blocks = get_root_blocks(db, document_id)
    enriched = [enrich_block_data_for_frontend(db, block) for block in blocks]
    return [BlockResponse.model_validate(item) for item in enriched]


@router.post("/documents/{document_id}/blocks", response_model=BlockResponse, status_code=status.HTTP_201_CREATED)
def insert_block(
    document_id: int,
    payload: BlockCreate,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    check_document_access(db, document_id, current_user.user_id)
    if not validate_block_constraints(db, document_id, payload.block_type_id):
        raise HTTPException(status_code=400, detail="Block constraints violated")

    block = create_block(
        db=db,
        document_id=document_id,
        block_type_id=payload.block_type_id,
        props=payload.props,
        previous_block_id=payload.previous_block_id,
    )
    db.commit()
    db.refresh(block)
    enriched = enrich_block_data_for_frontend(db, block)
    return BlockResponse.model_validate(enriched)


@router.patch("/blocks/{block_id}", response_model=BlockResponse)
def update_block(
    block_id: UUID,
    payload: BlockUpdate,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    block = db.execute(
        select(Block).filter(Block.block_id == block_id)
    ).scalars().first()
    if not block:
        raise HTTPException(status_code=404, detail="Block not found")
    check_document_access(db, block.document_id, current_user.user_id)

    updated = update_block_props(db, block_id, payload.props)
    if not updated:
        raise HTTPException(status_code=404, detail="Block not found")

    # Run block handler update hook when available.
    from app.models.document.block_types import get_block_type_handler

    handler = get_block_type_handler(updated.block_type_id)
    if handler:
        handler.on_update(db, updated.block_id, updated.document_id, updated.props)

    db.commit()
    db.refresh(updated)
    return BlockResponse.model_validate(enrich_block_data_for_frontend(db, updated))


@router.post("/blocks/{block_id}/move", response_model=BlockResponse)
def move_block(
    block_id: UUID,
    payload: BlockMove,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    block = db.execute(
        select(Block).filter(Block.block_id == block_id)
    ).scalars().first()
    if not block:
        raise HTTPException(status_code=404, detail="Block not found")
    check_document_access(db, block.document_id, current_user.user_id)

    if not can_reorder_block(db, block_id):
        raise HTTPException(status_code=400, detail="Block has fixed position")

    moved = move_block_after(
        db=db,
        document_id=block.document_id,
        block_id=block_id,
        previous_block_id=payload.previous_block_id,
    )
    if not moved:
        raise HTTPException(status_code=404, detail="Block not found")

    db.commit()
    db.refresh(moved)
    return BlockResponse.model_validate(enrich_block_data_for_frontend(db, moved))


@router.delete("/blocks/{block_id}", status_code=status.HTTP_204_NO_CONTENT)
def remove_block(
    block_id: UUID,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    block = db.execute(
        select(Block).filter(Block.block_id == block_id)
    ).scalars().first()
    if not block:
        raise HTTPException(status_code=404, detail="Block not found")
    check_document_access(db, block.document_id, current_user.user_id)

    if not can_delete_block(db, block_id):
        raise HTTPException(status_code=400, detail="Block is not removable")

    from app.models.document.block_types import get_block_type_handler

    handler = get_block_type_handler(block.block_type_id)
    if handler:
        handler.on_delete(db, block_id, block.document_id)

    if not delete_block(db, block.document_id, block_id):
        raise HTTPException(status_code=404, detail="Block not found")
    db.commit()


@router.post("/documents/{document_id}/commit", response_model=CommitResponse)
def commit_changes(
    document_id: int,
    commit_req: CommitRequest,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    check_document_access(db, document_id, current_user.user_id)
    success, message = commit_operations(
        db=db,
        document_id=document_id,
        ops=commit_req.ops,
    )
    if not success:
        raise HTTPException(status_code=400, detail=message)
    return CommitResponse(success=True, message=message)
"}

{"content":"/**
 * Block Component Registry
 * Maps block types to their React components
 */

import { ComponentType } from 'react'

export interface BlockData {
  block_id: string
  document_id: number
  previous_block_id: string | null
  next_block_id: string | null
  block_type_id: string
  props: Record<string, any>
  is_system: boolean
  is_removable: boolean
  fixed_position: number | null
  editable_fields?: string[]
  field_limits?: Record<string, number>
}

export interface BlockComponentProps {
  block: BlockData
  baselineProps: Record<string, any>
  onUpdate: (blockId: string, props: Record<string, any>) => void
  isReadOnly?: boolean
}

type BlockComponent = ComponentType<BlockComponentProps>

class BlockTypeRegistry {
  private components: Map<string, BlockComponent> = new Map()

  register(blockType: string, component: BlockComponent): void {
    this.components.set(blockType, component)
  }

  get(blockType: string): BlockComponent | undefined {
    return this.components.get(blockType)
  }

  has(blockType: string): boolean {
    return this.components.has(blockType)
  }

  getAll(): Map<string, BlockComponent> {
    return new Map(this.components)
  }
}

// Global registry instance
const registry = new BlockTypeRegistry()

export function registerBlockType(
  blockType: string,
  component: BlockComponent
): void {
  registry.register(blockType, component)
}

export function getBlockComponent(blockType: string): BlockComponent | undefined {
  return registry.get(blockType)
}

export function hasBlockComponent(blockType: string): boolean {
  return registry.has(blockType)
}

export default registry
"}

